#!/usr/bin/env python3
"""Regenerate paired-read figures from the checked public archive, offline and CPU-only."""
from __future__ import annotations

import argparse
import os
from pathlib import Path
import statistics
import sys
import tempfile

# The frozen archive rejects unlisted files, including import-generated bytecode.
sys.dont_write_bytecode = True
HERE = Path(__file__).resolve().parent
PUBLIC = HERE.parent / 'publication_results_v1'
sys.path.insert(0, str(PUBLIC))
import check as C
from plot_common import EvidenceError, METRICS, MIB, GIB, MODES, digest, encode, require

CHECKER_SOURCES = ('check.py', 'common.py', 'prespecified.py', 'reconcile.py')
RENDER_SOURCES = ('render_public.py', 'render.py', 'plot_common.py', 'renderer-pins.json', 'requirements-render.txt')
FIGURES = tuple('paired-read-' + name + '.' + suffix
                for name in ('latency', 'read-wait', 'accounting') for suffix in ('pdf', 'png')) + ('paired-read-preview.png',)
OUTPUTS = FIGURES + ('plot-data.json', 'layout.json', 'plot-manifest.json')


def source_hashes(root):
    hashes = {'analysis_v1/' + name: digest((HERE / name).read_bytes()) for name in RENDER_SOURCES}
    for name in CHECKER_SOURCES:
        actual = (PUBLIC / name).read_bytes()
        require(actual == (root / name).read_bytes(), 'public checker source differs: ' + name)
        hashes['publication_results_v1/' + name] = digest(actual)
    return hashes


def build_data(root=PUBLIC):
    """Only verified public receipts can supply measurements; never load saved plot data."""
    root = root.resolve()
    result, inventory = C.verify(root)
    hashes = source_hashes(root)
    analysis = result['analysis']
    order = C.load(root, 'design/order.json')['blocks']
    require(analysis['qualified_blocks'] == analysis['scheduled_blocks'] == 5
            and analysis['failed_or_incomplete_blocks'] == 0, 'all five complete paired blocks required')
    arms = []
    for checked in result['arms']:
        trial = checked['trial']
        prefix = 'arms/' + trial + '/'
        requests = [r for r in result['requests'] if r['trial'] == trial]
        measured = [r for r in requests if r['measured']]
        require(len(requests) == 12 and len(measured) == 5, 'request denominator differs')
        ledger = C.load(root, prefix + 'read-ledger-assessment.json')['final_read_ledger']
        resources = C.data(root, prefix + 'lifecycle.json.gz')['resources']
        config = C.data(root, prefix + 'configuration.json')
        selected = config['selected_device_alias']
        argv = config['argv']
        target = int(argv[argv.index('--cuda-device-budget-mb') + 1]) * MIB
        peak = checked['peak_device_sample_bytes']
        samples = checked['memory_sample_count']
        # Public lifecycle receipts retain collector summaries, not the raw sample stream.
        require(peak == resources['gpu_peak_bytes'][selected]
                == resources['memory_components']['gpu_peak_bytes'][selected], 'sampled device maximum differs')
        require(samples == resources['gpu_samples'] == resources['memory_components']['sample_count']
                == resources['memory_components']['gpu_samples'] and samples > 0, 'device sample count differs')
        require(resources['missing_gpu_attempts'] == 0 and resources['exact_peaks'] is False
                and resources['continuous_coverage'] is False, 'sampled gauge scope differs')
        host_peak = max(r['owner_peak_host_charge'] for r in requests)
        require(host_peak == ledger['stats']['peak_host_charged_bytes']
                == checked['pipeline_stats']['peak_host_charged_bytes'], 'host maximum differs')
        nfs_phases = {k: v['serverreadbytes'] for k, v in checked['nfs_phase_client_deltas'].items()}
        window_sum = sum(r['nfs_client_delta']['serverreadbytes'] for r in requests)
        gap = nfs_phases['requests_nfs'] - window_sum
        require(gap >= 0, 'request windows exceed enclosing NFS phase')
        arms.append(dict(
            trial=trial, mode=checked['mode'], metrics=checked['metrics'],
            requests=[dict(name=r['name'], phase=r['phase'], measured=r['measured'],
                           completion_tokens=r['usage']['completion_tokens'],
                           exact_token_oracle=r['exact_frozen_oracle'],
                           request_e2e_seconds=r['request_e2e_seconds'], ttft_seconds=r['ttft_seconds'],
                           decoder_invocations=r['decoder_invocations'], logical_counters=r['logical_counters'],
                           pipeline_nonpeak_deltas=r['pipeline_nonpeak_deltas'],
                           host_logical_peak_bytes=r['owner_peak_host_charge'],
                           nfs_client_serverreadbytes=r['nfs_client_delta']['serverreadbytes']) for r in requests],
            median_request_demand_wait_seconds=statistics.median(r['pipeline_nonpeak_deltas']['demand_wait_ns'] / 1e9 for r in measured),
            measured_demand_wait_seconds=sum(r['pipeline_nonpeak_deltas']['demand_wait_ns'] for r in measured) / 1e9,
            startup_probe_seconds=checked['startup_seconds'],
            logical_counters=checked['logical_counters'], pipeline_stats=checked['pipeline_stats'],
            final_logical_charge=checked['final_logical_charge'], host_logical_peak_bytes=host_peak,
            host_logical_limit_bytes=ledger['limits']['max_host_bytes'],
            sampled_device_max_bytes=peak, configured_device_target_bytes=target, device_sample_count=samples,
            nfs_phase_client_serverreadbytes=nfs_phases, nfs_request_window_sum_bytes=window_sum,
            nfs_between_request_windows_bytes=gap))
    # The accounting table and two gauge panels display a common value, not an average.
    for arm in arms[1:]:
        for field in ('host_logical_peak_bytes', 'host_logical_limit_bytes',
                      'sampled_device_max_bytes', 'configured_device_target_bytes'):
            require(arm[field] == arms[0][field], 'common plotted gauge differs: ' + field)
        for field in ('checkpoint_read_bytes', 'h2d_bytes'):
            require(arm['logical_counters'][field] == arms[0]['logical_counters'][field], 'common logical work differs')
        for field in ('verified_reads', 'wasted_read_bytes', 'unknown_reads', 'unknown_bytes'):
            require(arm['pipeline_stats'][field] == arms[0]['pipeline_stats'][field], 'common read accounting differs')
    by_trial = {a['trial']: a for a in arms}
    changes = []
    for block in order:
        b, l = (by_trial[block['block'] + '-' + mode] for mode in MODES)
        changes.append(dict(block=block['block'], execution_order=block['modes'],
                            wait_change_seconds=l['median_request_demand_wait_seconds'] - b['median_request_demand_wait_seconds'],
                            e2e_change_seconds=l['metrics']['request_e2e_seconds'] - b['metrics']['request_e2e_seconds'],
                            ttft_change_seconds=l['metrics']['ttft_seconds'] - b['metrics']['ttft_seconds']))
    aggregate = {k: dict(ratio=v['ratio'], descriptive_range=v['interval_ratio'],
                         draws=v['draws'], nearest_ranks_1based=v['ranks'], n=v['n'],
                         interpretation=v['interpretation']) for k, v in analysis['aggregate'].items()}
    return dict(
        schema='ferrule.paired-read.public-plot-data.v1',
        provenance=dict(input_manifest_path='publication_results_v1/manifest.json',
                        input_manifest_sha256=digest((root / 'manifest.json').read_bytes()),
                        input_count=inventory['files'], verified_public_inventory=inventory, source_hashes=hashes,
                        verification='check.verify: every public member, compressed and expanded hashes, original pins, full reconstruction and bootstrap enumeration',
                        device_sample_scope='Checked public collector-summary maxima and counts; raw device sample streams are not in the public archive',
                        time_policy='No analysis timestamp; only bound recorded measurements',
                        privacy_policy='Only public archive members; no private inputs or private derivation imports'),
        design=dict(independent_unit='paired block', n=5, measured_requests_per_arm=5,
                    total_measured_requests=50, order=order, retries=0, replacements=0,
                    historical_studies_pooled=False, instrumented=True,
                    startup_scope='recorded launch-to-ready probe; not lifecycle elapsed time or a request',
                    scientific_acceptance=False),
        denominators=analysis['denominators'], coverage=result['coverage'],
        paired=dict(blocks=analysis['blocks'], aggregate=aggregate, scheduled_blocks=5,
                    qualified_blocks=5, failed_or_incomplete_blocks=0),
        arms=arms, wait_latency_changes=changes, excluded_historical_attempts=result['historical_studies'],
        units=dict(bytes_per_MiB=MIB, bytes_per_GiB=GIB, nanoseconds_per_second=10**9),
        unknowns=dict(startup_pid_io_delta=None, shutdown_pid_io_delta=None, startup_logical_read_bytes=None,
                      physical_nas_backend_bytes=None, owned_process_gpu_peak_bytes=None,
                      universal_physical_release=None, continuous_device_peak_bytes=None,
                      causal_critical_path_savings_seconds=None),
        interpretation=dict(
            bootstrap='Exact 3125 paired-block resamples; nearest ranks 79 and 3047; descriptive, not coverage-guaranteed',
            wait='Sum host demand_wait_ns per invocation within a measured request, then median of five requests per arm; not GPU overlap or a causal latency decomposition',
            accounting='Requested host-to-device bytes names the existing h2d_bytes application counter (128811927312 per lifecycle), not measured physical bus traffic. Reader totals are 128811263616 bytes; equal across modes, not to one another',
            memory='Logical host-reservation maximum and device-wide sampled maximum; separate scopes, not RSS or exact process-owned GPU bytes. Do not add gauges or sum lifetime peaks',
            cache='Shared NFS client, not physical NAS traffic. Fresh servers do not establish cold caches. Phase totals include bytes between request windows',
            quality='900 worker-enqueued tokens: 110 exact eight-token oracle requests and 10 length-only two-token smoke requests; SSE events are not tokens',
            limitations='One instrumented n=5 study; no significance, power, repetition-based confidence, physical-release or physical-backend-I/O claim'))


def generate(root=PUBLIC):
    # Fail closed on the complete archive before importing the plotting dependencies.
    data = build_data(root)
    import render as R
    renderer = R.toolchain()
    pins = C.decode((HERE / 'renderer-pins.json').read_bytes())
    require({k: v for k, v in renderer.items() if k != 'renderer_source_sha256'} == pins,
            'renderer environment/font pins differ; see renderer-pins.json and requirements-render.txt')
    data['provenance'].update(generator_sha256=digest(encode(data['provenance']['source_hashes'])),
                              renderer_source_sha256=renderer['renderer_source_sha256'],
                              renderer_toolchain_sha256=digest(encode(renderer)), renderer=renderer)
    rendered, layout = R.render_figures(data, renderer, creator='analysis_v1/render_public.py')
    outputs = {Path(path).name: content for path, content in rendered.items()}
    outputs['plot-data.json'] = encode(data)
    outputs['layout.json'] = encode(layout)
    manifest = dict(schema='ferrule.paired-read.public-plot-manifest.v1',
                    provenance=data['provenance'], renderer=renderer,
                    artifacts={name: digest(content) for name, content in sorted(outputs.items())},
                    policy='Portable basenames; manifest excludes its own recursive hash. Public measurement manifest is read-only. Check verifies actual output hashes and rederives every byte')
    outputs['plot-manifest.json'] = encode(manifest)
    require(set(outputs) == set(OUTPUTS), 'unexpected output set')
    return outputs, data


def check_outputs(directory, expected):
    """Check actual output hashes as well as regenerated bytes, including the manifest."""
    manifest = C.decode((directory / 'plot-manifest.json').read_bytes())
    require(set(manifest['artifacts']) == set(OUTPUTS) - {'plot-manifest.json'}, 'output manifest membership differs')
    for name in OUTPUTS:
        path = directory / name
        require(path.is_file() and not path.is_symlink(), 'missing/nonregular output: ' + name)
        content = path.read_bytes()
        if name != 'plot-manifest.json':
            require(digest(content) == manifest['artifacts'][name], 'output hash differs: ' + name)
        require(content == expected[name], 'stale regenerated output: ' + name)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--public-root', type=Path, default=PUBLIC, help='Complete public archive (default: sibling publication_results_v1)')
    parser.add_argument('--output-dir', type=Path, required=True, help='Explicit output directory; all ten generated files use portable basenames')
    parser.add_argument('--check', action='store_true', help='Verify public inputs, re-render and byte-check this output directory; no output writes')
    args = parser.parse_args(argv)
    try:
        root, output = args.public_root.resolve(), args.output_dir.resolve()
        require(output != root and root not in output.parents, 'output must be outside the frozen public archive')
        with tempfile.TemporaryDirectory(prefix='paired-read-mpl-') as cache:
            old_cache = os.environ.get('MPLCONFIGDIR')
            os.environ['MPLCONFIGDIR'] = cache
            try:
                outputs, data = generate(root)
            finally:
                if old_cache is None:
                    os.environ.pop('MPLCONFIGDIR', None)
                else:
                    os.environ['MPLCONFIGDIR'] = old_cache
        if args.check:
            check_outputs(output, outputs)
        else:
            output.mkdir(parents=True, exist_ok=True)
            require(all(not (output / name).is_symlink() for name in outputs), 'refusing symlink output')
            for name, content in outputs.items():
                (output / name).write_bytes(content)
            check_outputs(output, outputs)
        print(('CHECKED' if args.check else 'GENERATED') + ': 3 PDFs, 3 PNGs, preview, data, layout, manifest')
        print(f"PASS: {data['provenance']['input_count']} public files; 5 blocks; 120 requests; 900 actual tokens; 1020 invocations")
        print('L/B ratios: ' + ', '.join(f"{k}={data['paired']['aggregate'][k]['ratio']:.8f}" for k in METRICS))
        return 0
    except (EvidenceError, C.Invalid) as error:
        print('EVIDENCE ERROR: ' + str(error))
        return 1
    except (OSError, ValueError, KeyError, TypeError, IndexError, ImportError) as error:
        print('ERROR: ' + type(error).__name__ + '; check the public archive and pinned renderer environment')
        return 1


if __name__ == '__main__':
    raise SystemExit(main())
